import { useEffect, useState } from "react";
import axios from "axios";

export default function TeacherCourses() {
  const [courses, setCourses] = useState([]);

  const [showForm, setShowForm] = useState(null);
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    due_date: ""
  });

  useEffect(() => {
    axios
      .get("/api/teachers/1/courses")
      .then((res) => setCourses(res.data))
      .catch((err) => console.log(err));
  }, []);

  const createAssignment = async (courseId) => {
    console.log("CLICKED:", courseId);
    console.log("FORM DATA:", formData);

    // ✅ validation (VERY IMPORTANT)
    if (!formData.title || !formData.description || !formData.due_date) {
      alert("Please fill all fields ❗");
      return;
    }

    try {
      const res = await axios.post("/api/assignments", {
        course_id: courseId,
          teacher_id: 1, // ✅ ADD THIS

        title: formData.title,
        description: formData.description,
        due_date: formData.due_date
      });

      console.log("RESPONSE:", res.data);

      if (res.data.success) {
        alert("Assignment created ✅");

        // reset form
        setShowForm(null);
        setFormData({
          title: "",
          description: "",
          due_date: ""
        });
      } else {
        alert("Failed to create assignment ❌");
      }
    } catch (err) {
      console.log("ERROR:", err);
      alert("Server error ❌");
    }
  };

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-6">
        Teacher Courses Page
      </h1>

      {courses.length === 0 ? (
        <p className="text-gray-500">No courses found</p>
      ) : (
        courses.map((course) => (
          <div
            key={course.course_id}
            className="bg-white p-5 rounded-lg shadow mb-5 border"
          >
            <h2 className="text-xl font-semibold mb-2">
              {course.course_name}
            </h2>

            <p className="text-sm text-gray-600">
              Code: {course.course_code}
            </p>

            <p className="text-sm text-gray-600">
              Duration: {course.duration_weeks} weeks
            </p>

            <p className="text-sm mb-2">
              Difficulty: {course.difficulty_level}
            </p>

            <div className="text-sm text-gray-700 mb-3">
              👨‍🎓 Students: {course.student_count} <br />
              📝 Assignments: {course.assignment_count} <br />
              ❓ Quizzes: {course.quiz_count}
            </div>

            {/* BUTTON */}
            <button
              onClick={() =>
                setShowForm(
                  showForm === course.course_id
                    ? null
                    : course.course_id
                )
              }
              className="bg-blue-500 hover:bg-blue-600 text-white px-3 py-1 rounded"
            >
              {showForm === course.course_id
                ? "Cancel"
                : "Create Assignment"}
            </button>

            {/* FORM */}
            {showForm === course.course_id && (
              <div className="mt-4 border p-4 rounded bg-gray-50">
                <input
                  type="text"
                  placeholder="Title"
                  value={formData.title}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      title: e.target.value
                    })
                  }
                  className="border p-2 w-full mb-2 rounded"
                />

                <textarea
                  placeholder="Description"
                  value={formData.description}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      description: e.target.value
                    })
                  }
                  className="border p-2 w-full mb-2 rounded"
                />

                <input
                  type="date"
                  value={formData.due_date}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      due_date: e.target.value
                    })
                  }
                  className="border p-2 w-full mb-3 rounded"
                />

                <button
                  onClick={() =>
                    createAssignment(course.course_id)
                  }
                  className="bg-green-500 hover:bg-green-600 text-white px-4 py-1 rounded"
                >
                  Submit
                </button>
              </div>
            )}
          </div>
        ))
      )}
    </div>
  );
}
